def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements having at least k deletable contiguous substrings.

    A nonempty substring is deletable by removing identical pairs and/or
    triples consisting of A, B, C. Equivalently, its three character counts
    have equal parity. Return the number of replacements modulo 998244353.

    n is the length of s (1 <= n <= 50); s contains A, B, C, and ?.
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)

    # Consecutive prefix states differ, so no state can occur more than
    # ceil((n+1)/2) times. Alternating two states maximizes equal pairs.
    if k > n * n // 4:
        return 0

    # Every assignment has at least this many equal prefix-state pairs.
    q, r = divmod(n + 1, 4)
    minimum = (4 - r) * q * (q - 1) // 2 + r * q * (q + 1) // 2
    if k <= minimum:
        return pow(3, s.count('?'), mod)

    # Encode A, B, C as the nonzero elements 1, 2, 3 of (Z/2Z)^2.
    # A substring is good iff its endpoints have equal prefix XOR.
    # Occupancies are indexed relative to the current prefix XOR:
    # index j counts past prefixes whose XOR differs from the current by j.
    # This removes the need to store the current XOR separately.
    dp = {(1, 0, 0, 0): 1}
    for ch in s:
        nxt = {}
        for (a, b, c, d), ways in dp.items():
            if ch == 'A' or ch == '?':
                state = (b + 1, a, d, c)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
            if ch == 'B' or ch == '?':
                state = (c + 1, d, a, b)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
            if ch == 'C' or ch == '?':
                state = (d + 1, c, b, a)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
        dp = nxt

    answer = 0
    for counts, ways in dp.items():
        good = sum(x * (x - 1) // 2 for x in counts)
        if good >= k:
            answer += ways
    return answer % mod

