def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether insertion, deletion, and replacement edit distance is at most k.

    k is at most 20; strings may contain up to 500000 characters.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    i = 0
    while i < n and i < m and s[i] == t[i]:
        i += 1
    if i == n and i == m:
        return True
    # A diagonal is consumed source length minus consumed target length.
    # Keep only its furthest reachable source position for each edit budget.
    previous = {0: i}
    for edits in range(1, k + 1):
        current = {}
        for diagonal in range(-edits, edits + 1):
            best = -1
            pos = previous.get(diagonal)
            if pos is not None and pos < n and pos - diagonal < m:
                best = pos + 1  # Replace.
            pos = previous.get(diagonal - 1)
            if pos is not None and pos < n:
                best = max(best, pos + 1)  # Delete from source.
            pos = previous.get(diagonal + 1)
            if pos is not None and pos - (diagonal + 1) < m:
                best = max(best, pos)  # Insert into source.
            if best < 0:
                continue
            j = best - diagonal
            while best < n and j < m and s[best] == t[j]:
                best += 1
                j += 1
            if best == n and j == m:
                return True
            current[diagonal] = best
        previous = current
    return False

