def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-color completions of the grid modulo 998244353.

    Every edge-sharing pair must contain different digits. H and W are
    positive and H * W <= 200; fixed digits are preserved.
    """
    mod = 998244353
    # Keep only the shorter dimension on the moving frontier. Its width
    # is at most 14 under the area bound.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Reject an already conflicting edge before building any states.
    for r in range(H):
        for c in range(W):
            digit = grid[r][c]
            if digit != '?':
                if r and grid[r - 1][c] == digit:
                    return 0
                if c and grid[r][c - 1] == digit:
                    return 0

    powers = [3 ** c for c in range(W)]
    # Base-three digits describe the latest processed cell in each column.
    # Before the first row, their initial values are ignored.
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            place = powers[c]
            choices = (0, 1, 2) if grid[r][c] == '?' else (int(grid[r][c]) - 1,)
            next_dp = {}
            for state, ways in dp.items():
                above = (state // place) % 3
                left = (state // powers[c - 1]) % 3 if c else -1
                for color in choices:
                    if (r and color == above) or color == left:
                        continue
                    new_state = state + (color - above) * place
                    next_dp[new_state] = (next_dp.get(new_state, 0) + ways) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

from functools import lru_cache


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers x in [num1, num2] whose digit sum is in [min_sum, max_sum].

    Return the count modulo 10^9 + 7.

    Args:
        num1: A numeric string representing the lower bound (1 <= num1 <= 10^22)
        num2: A numeric string representing the upper bound (num1 <= num2 <= 10^22)
        min_sum: The minimum allowed digit sum (1 <= min_sum <= 400)
        max_sum: The maximum allowed digit sum (min_sum <= max_sum <= 400)

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    modulus = 10**9 + 7

    def count_up_to(bound: str) -> int:
        digits = tuple(map(int, bound))
        length = len(digits)

        @lru_cache(None)
        def dp(position: int, total: int, tight: bool) -> int:
            if total > max_sum or total + 9 * (length - position) < min_sum:
                return 0
            if position == length:
                return int(min_sum <= total <= max_sum)
            limit = digits[position] if tight else 9
            return sum(
                dp(position + 1, total + digit, tight and digit == limit)
                for digit in range(limit + 1)
            ) % modulus

        return dp(0, 0, True)

    lower_is_good = min_sum <= sum(map(int, num1)) <= max_sum
    return (count_up_to(num2) - count_up_to(num1) + lower_is_good) % modulus

