def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements with at least k nonempty reducible substrings.

    A string is reducible precisely when its three letter counts have the
    same parity. Encode A, B, C as 1, 2, 3: this is equivalent to XOR zero.
    Thus the number of good substrings is the number of equal prefix pairs.
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)
    # Adjacent prefix states differ. Concentrating their visits into two
    # alternating states gives the largest possible number of equal pairs.
    if k > n * n // 4:
        return 0
    # The most evenly distributed visit counts give a universal lower bound.
    q, r = divmod(n + 1, 4)
    minimum = r * q * (q + 1) // 2 + (4 - r) * q * (q - 1) // 2
    if k <= minimum:
        return pow(3, s.count('?'), mod)

    # Counts are indexed relative to the current prefix XOR. Changing the
    # current state by x permutes the four indices by XOR x, then adds one
    # visit to index zero. This removes the need to store the current XOR.
    dp = {(1, 0, 0, 0): 1}
    for char in s:
        choices = (1, 2, 3) if char == '?' else ({'A': 1, 'B': 2, 'C': 3}[char],)
        nxt = {}
        for (a, b, c, d), ways in dp.items():
            for x in choices:
                if x == 1:
                    state = (b + 1, a, d, c)
                elif x == 2:
                    state = (c + 1, d, a, b)
                else:
                    state = (d + 1, c, b, a)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
        dp = nxt

    answer = 0
    for counts, ways in dp.items():
        good = sum(v * (v - 1) // 2 for v in counts)
        if good >= k:
            answer = (answer + ways) % mod
    return answer

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K orthogonal moves through distinct empty cells.

    Every empty starting cell is allowed, and reversed paths are counted
    separately. H and W are at most 10 and K is at most 11.
    """
    cells = [(r, c) for r in range(H) for c in range(W)
             if grid[r][c] == "."]
    if len(cells) <= K:
        return 0
    if K == 0:
        return len(cells)

    index = {cell: i for i, cell in enumerate(cells)}
    neighbors = []
    for r, c in cells:
        neighbors.append([index[(nr, nc)]
                          for nr, nc in ((r - 1, c), (r + 1, c),
                                         (r, c - 1), (r, c + 1))
                          if (nr, nc) in index])

    # A path needs K + 1 cells in a single connected component.
    seen = [False] * len(cells)
    starts = []
    for root in range(len(cells)):
        if seen[root]:
            continue
        component = [root]
        seen[root] = True
        for cell in component:
            for nxt in neighbors[cell]:
                if not seen[nxt]:
                    seen[nxt] = True
                    component.append(nxt)
        if len(component) > K:
            starts.extend(component)

    visited = [False] * len(cells)

    def search(cell: int, remaining: int) -> int:
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[cell]:
            if not visited[nxt]:
                visited[nxt] = True
                total += search(nxt, remaining - 1)
                visited[nxt] = False
        return total

    total = 0
    for start in starts:
        visited[start] = True
        total += search(start, K)
        visited[start] = False
    return total

from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Return the largest subtree whose degrees are 1 or 4, with a degree-4 vertex.

    The input is an undirected tree on vertices 1 through n. Return -1 if
    no alkane exists. Runs in O(n) time and O(n) space.
    """
    adjacency = [[] for _ in range(n + 1)]
    for u, v in edges:
        adjacency[u].append(v)
        adjacency[v].append(u)

    parent = [0] * (n + 1)
    order = [1]
    for u in order:
        for v in adjacency[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)

    # branch[u] includes u and assumes the edge to its parent is selected.
    # Thus u is either a leaf, or has exactly three selected children.
    branch = [1] * (n + 1)
    answer = -1
    for u in reversed(order):
        first = second = third = fourth = 0
        for v in adjacency[u]:
            if v == parent[u]:
                continue
            value = branch[v]
            if value >= first:
                first, second, third, fourth = value, first, second, third
            elif value >= second:
                second, third, fourth = value, second, third
            elif value >= third:
                third, fourth = value, third
            elif value > fourth:
                fourth = value

        if third:
            branch[u] = 1 + first + second + third
            if parent[u]:
                # The highest selected vertex may be u's parent, a leaf.
                answer = max(answer, branch[u] + 1)
        if fourth:
            # Here u itself is the highest selected vertex, of degree four.
            answer = max(answer, 1 + first + second + third + fourth)

    return answer

