def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-color completions of the grid modulo 998244353.

    Every edge-sharing pair must contain different digits. H and W are
    positive and H * W <= 200; fixed digits are preserved.
    """
    mod = 998244353
    # Keep only the shorter dimension on the moving frontier. Its width
    # is at most 14 under the area bound.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Reject an already conflicting edge before building any states.
    for r in range(H):
        for c in range(W):
            digit = grid[r][c]
            if digit != '?':
                if r and grid[r - 1][c] == digit:
                    return 0
                if c and grid[r][c - 1] == digit:
                    return 0

    powers = [3 ** c for c in range(W)]
    # Base-three digits describe the latest processed cell in each column.
    # Before the first row, their initial values are ignored.
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            place = powers[c]
            choices = (0, 1, 2) if grid[r][c] == '?' else (int(grid[r][c]) - 1,)
            next_dp = {}
            for state, ways in dp.items():
                above = (state // place) % 3
                left = (state // powers[c - 1]) % 3 if c else -1
                for color in choices:
                    if (r and color == above) or color == left:
                        continue
                    new_state = state + (color - above) * place
                    next_dp[new_state] = (next_dp.get(new_state, 0) + ways) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements with at least k nonempty reducible substrings.

    A string is reducible precisely when its three letter counts have the
    same parity. Encode A, B, C as 1, 2, 3: this is equivalent to XOR zero.
    Thus the number of good substrings is the number of equal prefix pairs.
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)
    # Adjacent prefix states differ. Concentrating their visits into two
    # alternating states gives the largest possible number of equal pairs.
    if k > n * n // 4:
        return 0
    # The most evenly distributed visit counts give a universal lower bound.
    q, r = divmod(n + 1, 4)
    minimum = r * q * (q + 1) // 2 + (4 - r) * q * (q - 1) // 2
    if k <= minimum:
        return pow(3, s.count('?'), mod)

    # Counts are indexed relative to the current prefix XOR. Changing the
    # current state by x permutes the four indices by XOR x, then adds one
    # visit to index zero. This removes the need to store the current XOR.
    dp = {(1, 0, 0, 0): 1}
    for char in s:
        choices = (1, 2, 3) if char == '?' else ({'A': 1, 'B': 2, 'C': 3}[char],)
        nxt = {}
        for (a, b, c, d), ways in dp.items():
            for x in choices:
                if x == 1:
                    state = (b + 1, a, d, c)
                elif x == 2:
                    state = (c + 1, d, a, b)
                else:
                    state = (d + 1, c, b, a)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
        dp = nxt

    answer = 0
    for counts, ways in dp.items():
        good = sum(v * (v - 1) // 2 for v in counts)
        if good >= k:
            answer = (answer + ways) % mod
    return answer

