from functools import lru_cache


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers x in [num1, num2] whose digit sum is in [min_sum, max_sum].

    Return the count modulo 10^9 + 7.

    Args:
        num1: A numeric string representing the lower bound (1 <= num1 <= 10^22)
        num2: A numeric string representing the upper bound (num1 <= num2 <= 10^22)
        min_sum: The minimum allowed digit sum (1 <= min_sum <= 400)
        max_sum: The maximum allowed digit sum (min_sum <= max_sum <= 400)

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    modulus = 10**9 + 7

    def count_up_to(bound: str) -> int:
        digits = tuple(map(int, bound))
        length = len(digits)

        @lru_cache(None)
        def dp(position: int, total: int, tight: bool) -> int:
            if total > max_sum or total + 9 * (length - position) < min_sum:
                return 0
            if position == length:
                return int(min_sum <= total <= max_sum)
            limit = digits[position] if tight else 9
            return sum(
                dp(position + 1, total + digit, tight and digit == limit)
                for digit in range(limit + 1)
            ) % modulus

        return dp(0, 0, True)

    lower_is_good = min_sum <= sum(map(int, num1)) <= max_sum
    return (count_up_to(num2) - count_up_to(num1) + lower_is_good) % modulus

def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether s can be changed into t with at most k edits.

    An edit inserts, deletes, or replaces one character. The strings may
    contain up to 500000 characters, and k is at most 20.

    >>> can_transform(3, 'abc', 'awtf')
    True
    >>> can_transform(2, 'abc', 'awtf')
    False
    >>> can_transform(17, 'twothousandtwentyfour', 'happynewyear')
    True
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t or k >= max(n, m):
        return True

    # A diagonal is x - y, where x and y are consumed prefix lengths.
    # For a fixed edit count and diagonal, only the furthest x matters:
    # any earlier position cannot overtake it by following matching chars.
    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    frontier = {0: x}

    for edits in range(1, k + 1):
        following = {}
        for diagonal, x in frontier.items():
            y = x - diagonal
            if x < n:
                # Delete s[x].
                d = diagonal + 1
                if x + 1 > following.get(d, -1):
                    following[d] = x + 1
            if y < m:
                # Insert t[y].
                d = diagonal - 1
                if x > following.get(d, -1):
                    following[d] = x
            if x < n and y < m:
                # Replace s[x] with t[y].
                if x + 1 > following.get(diagonal, -1):
                    following[diagonal] = x + 1

        for diagonal, x in following.items():
            y = x - diagonal
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if x == n and y == m:
                return True
            following[diagonal] = x
        frontier = following
    return False

