def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    """Count monotone paths outside the closed rectangular hole."""
    from array import array

    mod = 998244353
    if L == 0 and R == W and D == 0 and U == H:
        return 0

    limit = W + H + 4
    fac = array("I", [1]) * (limit + 1)
    inv = array("I", [1]) * (limit + 1)
    for i in range(1, limit + 1):
        fac[i] = fac[i - 1] * i % mod
    inv[limit] = pow(fac[limit], mod - 2, mod)
    for i in range(limit, 0, -1):
        inv[i - 1] = inv[i] * i % mod

    def choose(n, k):
        return fac[n] * inv[k] % mod * inv[n - k] % mod

    def total(w, h):
        if w < 0 or h < 0:
            return 0
        return (choose(w + h + 4, w + 2)
                - (w + 2) * (h + 2) - 1) % mod

    bad = (total(W - L, H - D)
           - total(W - R - 1, H - D)
           - total(W - L, H - U - 1)
           + total(W - R - 1, H - U - 1)) % mod

    if L > 0:
        for y in range(D, U + 1):
            prefix = choose(L + y + 1, L) - 1
            suffix = choose(W - L + H - y + 2, W - L + 1) - 1
            bad = (bad + prefix * suffix) % mod
    if D > 0:
        for x in range(L, R + 1):
            prefix = choose(x + D + 1, D) - 1
            suffix = choose(W - x + H - D + 2, H - D + 1) - 1
            bad = (bad + prefix * suffix) % mod

    return (total(W, H) - bad) % mod

