from typing import List


def determine_winner(n: int, a: List[int]) -> str:
    """Return the optimal winner of the decrement-and-mark game."""
    odd = sum(value & 1 for value in a)
    if n == 1:
        winning = True
    elif n == 2:
        winning = False
    elif n == 3:
        winning = odd > 0
