def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Return the largest subtree whose degrees are 1 or 4, with a degree-4 vertex.

    The input is an undirected tree on vertices 1 through n. Return -1 if
    no alkane exists. Runs in O(n) time and O(n) space.
    """
    adjacency = [[] for _ in range(n + 1)]
    for u, v in edges:
        adjacency[u].append(v)
        adjacency[v].append(u)

    parent = [0] * (n + 1)
    order = [1]
    for u in order:
        for v in adjacency[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)

    # branch[u] includes u and assumes the edge to its parent is selected.
    # Thus u is either a leaf, or has exactly three selected children.
    branch = [1] * (n + 1)
    answer = -1
    for u in reversed(order):
        first = second = third = fourth = 0
        for v in adjacency[u]:
            if v == parent[u]:
                continue
            value = branch[v]
            if value >= first:
                first, second, third, fourth = value, first, second, third
            elif value >= second:
                second, third, fourth = value, second, third
            elif value >= third:
                third, fourth = value, third
            elif value > fourth:
                fourth = value

        if third:
            branch[u] = 1 + first + second + third
            if parent[u]:
                # The highest selected vertex may be u's parent, a leaf.
                answer = max(answer, branch[u] + 1)
        if fourth:
            # Here u itself is the highest selected vertex, of degree four.
            answer = max(answer, 1 + first + second + third + fourth)

    return answer

def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether s can be changed into t with at most k edits.

    An edit inserts, deletes, or replaces one character. The strings may
    contain up to 500000 characters, and k is at most 20.

    >>> can_transform(3, 'abc', 'awtf')
    True
    >>> can_transform(2, 'abc', 'awtf')
    False
    >>> can_transform(17, 'twothousandtwentyfour', 'happynewyear')
    True
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t or k >= max(n, m):
        return True

    # A diagonal is x - y, where x and y are consumed prefix lengths.
    # For a fixed edit count and diagonal, only the furthest x matters:
    # any earlier position cannot overtake it by following matching chars.
    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    frontier = {0: x}

    for edits in range(1, k + 1):
        following = {}
        for diagonal, x in frontier.items():
            y = x - diagonal
            if x < n:
                # Delete s[x].
                d = diagonal + 1
                if x + 1 > following.get(d, -1):
                    following[d] = x + 1
            if y < m:
                # Insert t[y].
                d = diagonal - 1
                if x > following.get(d, -1):
                    following[d] = x
            if x < n and y < m:
                # Replace s[x] with t[y].
                if x + 1 > following.get(diagonal, -1):
                    following[diagonal] = x + 1

        for diagonal, x in following.items():
            y = x - diagonal
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if x == n and y == m:
                return True
            following[diagonal] = x
        frontier = following
    return False

