from functools import lru_cache


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers x in [num1, num2] whose digit sum is in [min_sum, max_sum].

    Return the count modulo 10^9 + 7.

    Args:
        num1: A numeric string representing the lower bound (1 <= num1 <= 10^22)
        num2: A numeric string representing the upper bound (num1 <= num2 <= 10^22)
        min_sum: The minimum allowed digit sum (1 <= min_sum <= 400)
        max_sum: The maximum allowed digit sum (min_sum <= max_sum <= 400)

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    modulus = 10**9 + 7

    def count_up_to(bound: str) -> int:
        digits = tuple(map(int, bound))
        length = len(digits)

        @lru_cache(None)
        def dp(position: int, total: int, tight: bool) -> int:
            if total > max_sum or total + 9 * (length - position) < min_sum:
                return 0
            if position == length:
                return int(min_sum <= total <= max_sum)
            limit = digits[position] if tight else 9
            return sum(
                dp(position + 1, total + digit, tight and digit == limit)
                for digit in range(limit + 1)
            ) % modulus

        return dp(0, 0, True)

    lower_is_good = min_sum <= sum(map(int, num1)) <= max_sum
    return (count_up_to(num2) - count_up_to(num1) + lower_is_good) % modulus

from math import gcd
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any supplied denomination.

    Coins of different denominations cannot be combined. There are 1-15
    distinct positive denominations, each 1-25, and 1 <= k <= 2*10**9.
    """
    # A denomination divisible by a smaller one adds no new amounts.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    upper = denominations[0] * k
    # Inclusion-exclusion coefficients, combined for subsets with equal LCM.
    coefficients = {}
    for coin in denominations:
        changes = {coin: 1}
        for multiple, coefficient in coefficients.items():
            common = multiple // gcd(multiple, coin) * coin
            if common <= upper:
                changes[common] = changes.get(common, 0) - coefficient
        for multiple, coefficient in changes.items():
            value = coefficients.get(multiple, 0) + coefficient
            if value:
                coefficients[multiple] = value
            else:
                coefficients.pop(multiple, None)

    lower = 1
    while lower < upper:
        middle = (lower + upper) // 2
        count = sum(coefficient * (middle // multiple)
                    for multiple, coefficient in coefficients.items())
        if count >= k:
            upper = middle
        else:
            lower = middle + 1
    return lower

